import * as React from "react"
import Seo from "../components/Seo"
import { scan, whereAmI } from "../lib/qr-tracking"

/**
 * What a tracked QR code opens — FCS-087.
 * ============================================================================
 * /q/?c=<code>. Somebody scanned a code on a van, a flyer or a shop window;
 * this notes that they did, and sends them on to where the code points.
 *
 * ── IT TELLS THEM WHAT IT IS DOING ─────────────────────────────────────────
 * The page counts visits and, if the visitor allows it, notes roughly where
 * they are. A stranger's phone asking for their location with no explanation
 * looks like something worse than it is, so the reason is on screen while the
 * browser's own prompt is up, and nothing is read without that prompt.
 *
 * ── NOBODY IS LEFT HERE ────────────────────────────────────────────────────
 * Whatever happens to the counting — no permission, no network, a blip — the
 * visitor still goes where the code points. The only way to stay on this page
 * is a code that does not exist or has been paused, and that says so.
 */

const QrLanding = ({ location }) => {
  const [state, setState] = React.useState("working")

  React.useEffect(() => {
    const code = new URLSearchParams(location?.search || window.location.search).get("c") || ""
    let alive = true
    ;(async () => {
      if (!code) return alive && setState("missing")
      const where = await whereAmI()
      const destination = await scan(code, where)
      if (!alive) return
      if (!destination) return setState("gone")
      window.location.replace(destination)
    })()
    return () => {
      alive = false
    }
  }, [location])

  return (
    <main style={{ minHeight: "70vh", display: "grid", placeItems: "center", padding: "32px 20px" }}>
      <div style={{ maxWidth: 420, textAlign: "center" }}>
        {state === "working" ? (
          <>
            <h1 style={{ fontSize: 22, margin: "0 0 10px" }}>Taking you there…</h1>
            <p style={{ margin: 0, fontSize: 14.5, lineHeight: 1.6, color: "#5b6b7c" }}>
              This link counts how many people scan it. If your phone asks to share your location,
              that only helps the owner see roughly where it was scanned. You can say no and
              nothing changes.
            </p>
          </>
        ) : (
          <>
            <h1 style={{ fontSize: 22, margin: "0 0 10px" }}>
              {state === "missing" ? "No code in that link" : "This code is not active"}
            </h1>
            <p style={{ margin: 0, fontSize: 14.5, lineHeight: 1.6, color: "#5b6b7c" }}>
              {state === "missing"
                ? "The link is missing its code. Try scanning it again."
                : "It may have been paused or removed by whoever made it."}
            </p>
          </>
        )}
      </div>
    </main>
  )
}

export const Head = () => <Seo title="Redirecting" description="Opening a link." noindex />

export default QrLanding
